import math

def check_integer(n):
    """Checks if 3*((n+2)! + 1) is divisible by 2n - 1."""
    if n < 0:
        return False

    numerator = 3 * (math.factorial(n + 2) + 1)
    denominator = 2 * n - 1

    if denominator == 0:
        # Should not happen for n >= 0
        return False

    if numerator % denominator == 0:
        return True
    else:
        return False

solutions = []
for n in range(16, 51):
    if check_integer(n):
        solutions.append(n)

print("Solutions found for n in [16, 50]:", solutions)
